import{z as s,x as A,o as E,c as d,q as l,j as n,D as t,d as r,s as i,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"干涉仪对光栅编码器","description":"","frontmatter":{"title":"干涉仪对光栅编码器","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/interferometer-vs-encoder.md","filePath":"litho/interferometer-vs-encoder.md","lastUpdated":1791063341000}'),p={name:"litho/interferometer-vs-encoder.md"};function m(h,a,f,D,c,F){const o=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=l('<h1 id="干涉仪对光栅编码器" tabindex="-1">干涉仪对光栅编码器 <a class="header-anchor" href="#干涉仪对光栅编码器" aria-label="Permalink to &quot;干涉仪对光栅编码器&quot;">​</a></h1><div class="epigraph"><p>工件台要知道自己在哪。激光干涉仪走光程，光栅编码器走尺。空气、阿贝臂和污染对两者的打法不同。</p><footer>—— 对照扫描投影机双频干涉仪与光栅编码器公开方案；套刻见 [litho-overlay](/litho/litho-overlay)</footer></div><p><a href="/litho/lens-contamination">上一课</a>把物镜表面污染收束，并点名下一单元是台子上的计量脏。本课打开「工件台与传感」：位置反馈选干涉仪还是编码器。不重写套刻预算分解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纳米套刻要求台位置在扫描全程可溯源。干涉仪把位移变成光程差，空气折射率（温、压、湿、CO₂）直接进读数，阿贝臂误差把俯仰变成横向。光栅尺把位移变成莫尔条纹，对空气不敏感，但对尺的热胀、安装与脏敏感。把「台不准」写成一种传感器，会选错补偿。</p><p><span class="marginnote">「阿贝臂」翻译成大白话：测量传感器与真正干活的曝光点之间隔着一段横向距离，这段「手臂」会把台子的微小俯仰放大成横向读数误差。代个数：偏 50 mm、俯仰仅 1 微弧度，横向误差就是 \\(50\\,\\mathrm{mm}\\times10^{-6}=50\\) nm——对套刻预算是天文数字，所以传感器必须尽量与曝光面对齐。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>量产机常编码器为主、干涉仪交叉校验或分轴。环境：干涉仪要气浴与波长补偿；编码器要尺温与清洁。校准把两种读数在同一轨迹上对起来，残差进套刻模型。</p>',8)),(E(),n(B,null,{default:t(()=>[i(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IF%5B%22%E6%BF%80%E5%85%89%E5%B9%B2%E6%B6%89%E4%BB%AA%22%5D%20--%3E%20AIR%5B%22%E7%A9%BA%E6%B0%94%E6%8A%98%E5%B0%84%E7%8E%87%22%5D%0A%20%20ENC%5B%22%E5%85%89%E6%A0%85%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%20--%3E%20SCALE%5B%22%E5%B0%BA%E7%83%AD%20%2F%20%E8%84%8F%22%5D%0A%20%20IF%20--%3E%20POS%5B%22%E5%8F%B0%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20ENC%20--%3E%20POS%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"EUV 真空里空气项消失，干涉仪环境变了，但不等于编码器自动更好：磁浮台与热仍在。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"干涉相位 \\(\\Delta\\phi = 4\\pi n L/\\lambda\\)。\\(n\\) 漂等于假运动。光栅周期固定，误差来自尺本身与读头间隙。两者的噪声谱不同：气流是低频，读头振动可以更高频。",-1)),(E(),n(B,null,{default:t(()=>[i(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20DRIFT%5B%22%E7%A9%BA%E6%B0%94%20n%20%E6%BC%82%E7%A7%BB%22%5D%20--%3E%20PH%5B%22%E7%9B%B8%E4%BD%8D%204%CF%80nL%2F%CE%BB%20%E5%8F%98%22%5D%0A%20%20PH%20--%3E%20FALSE%5B%22%E8%AF%BB%E6%95%B0%E5%87%BA%E7%8E%B0%E5%81%87%E8%BF%90%E5%8A%A8%22%5D%0A%20%20TEMP%5B%22%E5%B0%BA%E6%B8%A9%E5%8F%98%E5%8C%96%22%5D%20--%3E%20EXP%5B%22%E5%85%89%E6%A0%85%E5%B0%BA%E7%83%AD%E8%83%80%E5%86%B7%E7%BC%A9%22%5D%0A%20%20EXP%20--%3E%20FALSE2%5B%22%E5%88%BB%E5%BA%A6%E6%9C%AC%E8%BA%AB%E5%9C%A8%E5%8A%A8%22%5D%0A%20%20FALSE%20--%3E%20C1%5B%22%E8%A1%A5%E5%81%BF%EF%BC%9A%E6%B3%A2%E9%95%BF%20%2F%20%E6%B0%94%E6%B5%B4%22%5D%0A%20%20FALSE2%20--%3E%20C2%5B%22%E8%A1%A5%E5%81%BF%EF%BC%9A%E5%B0%BA%E6%B8%A9%E4%BC%A0%E6%84%9F%20%2F%20%E6%B8%85%E6%B4%81%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>这张图回答的问题是：两种传感器各自的误差沿哪条物理链混进读数，对应的补偿杠杆又分别在哪——拿错杠杆，补偿本身就是新的误差源。</p><p><span class="marginnote">激光干涉仪的测距原理是「数条纹」：台子每移动半个波长（HeNe 激光约 316 nm），干涉条纹就明暗交替一次；数出次数乘上半波长就是位移，分辨率能做到亚纳米。但它读的是「光走过的路」，不是「台子走的路」——中间的空气全算在账里。</span></p><p><span class="marginnote">直觉类比：光栅编码器像贴在导轨上的卷尺，读头贴着读刻度，尺上刻度是哪就是哪，天生不管空气；代价是这把「米尺」自己会热胀冷缩——尺一变长，所有刻度一起错。所以编码器机的关键日常是尺温控制与清洁，而不是气浴。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课调平：竖直方向另一套传感器，不要用同一套 XY 编码器冒充。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>干涉仪吃空气与阿贝臂；编码器吃尺与脏。</li><li>套刻补偿必须声明用了哪路反馈。</li><li>出处：扫描机位置计量通识；套刻课。</li></ul>',7))])}const _=s(p,[["render",m]]);export{C as __pageData,_ as default};
